class Solution:
    def minimumCost(self, m: int, horizontalCut: list[int], verticalCut: list[int]) -> int:
        h = sorted(horizontalCut, reverse=True)
        v = sorted(verticalCut, reverse=True)
        i = j = ans = 0
        hp = vp = 1
        while i < len(h) or j < len(v):
            if j == len(v) or (i < len(h) and h[i] >= v[j]):
                ans += h[i] * vp
                hp += 1
                i += 1
            else:
                ans += v[j] * hp
                vp += 1
                j += 1
        return ans

