class Solution {
public:
    long long minimumCost(int m, vector<int>& horizontalCut, vector<int>& verticalCut) {
        sort(horizontalCut.rbegin(), horizontalCut.rend());
        sort(verticalCut.rbegin(), verticalCut.rend());
        long long ans = 0;
        int i = 0, j = 0, hp = 1, vp = 1;
        while (i < (int)horizontalCut.size() || j < (int)verticalCut.size()) {
            if (j == (int)verticalCut.size() ||
                (i < (int)horizontalCut.size() && horizontalCut[i] >= verticalCut[j])) {
                ans += (long long)horizontalCut[i++] * vp; hp++;
            } else {
                ans += (long long)verticalCut[j++] * hp; vp++;
            }
        }
        return ans;
    }
};

