class Solution {
    public long minimumCost(int m, int[] horizontalCut, int[] verticalCut) {
        Arrays.sort(horizontalCut);
        Arrays.sort(verticalCut);
        int i = horizontalCut.length - 1, j = verticalCut.length - 1;
        long ans = 0;
        int hp = 1, vp = 1;
        while (i >= 0 || j >= 0) {
            if (j < 0 || (i >= 0 && horizontalCut[i] >= verticalCut[j])) {
                ans += (long) horizontalCut[i--] * vp; hp++;
            } else {
                ans += (long) verticalCut[j--] * hp; vp++;
            }
        }
        return ans;
    }
}

