import heapq
class Solution:
    def minimumCost(self, m: int, horizontalCut: list[int], verticalCut: list[int]) -> int:
        heap = [(-c, 0) for c in horizontalCut] + [(-c, 1) for c in verticalCut]
        heapq.heapify(heap)
        ans, hp, vp = 0, 1, 1
        while heap:
            negc, kind = heapq.heappop(heap)
            c = -negc
            if kind == 0:
                ans += c * vp; hp += 1
            else:
                ans += c * hp; vp += 1
        return ans

