class Solution {
public:
    long long minimumCost(int m, vector<int>& horizontalCut, vector<int>& verticalCut) {
        priority_queue<pair<int,int>> pq;
        for (int c : horizontalCut) pq.push({c, 0});
        for (int c : verticalCut) pq.push({c, 1});
        long long ans = 0;
        int hp = 1, vp = 1;
        while (!pq.empty()) {
            auto [c, kind] = pq.top(); pq.pop();
            if (kind == 0) { ans += (long long)c * vp; hp++; }
            else { ans += (long long)c * hp; vp++; }
        }
        return ans;
    }
};

