class Solution {
    public long minimumCost(int m, int[] horizontalCut, int[] verticalCut) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        for (int c : horizontalCut) pq.offer(new int[]{c, 0});
        for (int c : verticalCut) pq.offer(new int[]{c, 1});
        long ans = 0;
        int hp = 1, vp = 1;
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            if (top[1] == 0) { ans += (long) top[0] * vp; hp++; }
            else { ans += (long) top[0] * hp; vp++; }
        }
        return ans;
    }
}

